def sample_poisson(lam: float, rng: random.Random) -> int:
    lam = max(0.0, lam)
    try:
        # Seed a local numpy Generator from the provided rng for reproducibility
        ss = np.random.SeedSequence(rng.getrandbits(128))
        rg = np.random.default_rng(ss)
        return int(rg.poisson(lam))
    except Exception:
        # Python-only fallback (Knuth)
        L = math.exp(-lam)
        k = 0
        p = 1.0
        while p > L:
            k += 1
            p *= rng.random()
        return max(0, k - 1)

